from s114_course_common import teach
S='pupil-response-p1'
teach(S,'normal-pupil-1',[
(0,'瞳孔是洞，虹膜肌肉讓洞大小改變','縮瞳和散瞳在說孔徑，不是在說視力好壞。',[('Miosis縮瞳','括約肌像束口帶收緊，副交感促使縮小'),('Mydriasis散瞳','擴張肌往外拉，交感促使放大'),('正常大小','受亮暗、年齡、藥物等影響，需記照明')],'下頁1～8、室內3～5mm等為課堂參考範圍，不能不看情境就判疾病。'),
(2,'不等瞳：先比哪一種光線下差更大','差更大時，找那個該動卻動不好的瞳孔。',[('暗處差較大','小瞳孔放不開，想交感路徑'),('亮處差較大','大瞳孔縮不下，想副交感、虹膜或藥物'),('差不多','可能生理性，但還要病史、時間與其他反應')],'兩眼不一樣大叫anisocoria；它與RAPD輸入不對稱不是同一件事。'),
(4,'看近要同時對焦、對準、縮孔','三聯是三個動作配合，不是都叫調節。',[('調節accommodation','水晶體增加收光力量'),('集合convergence','兩眼向鼻側轉，對同一近目標'),('縮瞳miosis','虹膜括約肌收縮，孔變小')],'請病人看近的小目標是在引出整組近反應；量NPA和NPC時終點仍不同。')])
teach(S,'reflex-pathway-1',[
(0,'照右眼，訊號分送到兩眼','照到那眼叫直接；另一眼叫間接／共感。',[('傳入afferent','網膜→CN II視神經→中腦頂蓋前區'),('中腦分送','到雙側E–W副交感核'),('傳出efferent','各側CN III→睫狀神經節→短睫神經→括約肌')],'光反射不必先繞LGN和枕葉視覺皮質；能否看見與能否光反射要分開。'),
(2,'RAPD：換到弱輸入眼，兩眼相對放大','不是手電筒把病眼直接照大。',[('右輸入較弱','照左時命令較強，兩眼都縮'),('換照右','命令比剛才弱，兩眼相對散大'),('比較前提','兩側亮度距離與停留相近，評估傳出反應是否可用')],'RAPD＝relative afferent pupillary defect；不對稱視神經或廣泛網膜病變可出現，不能唯一確診視神經炎。'),
(4,'光近分離：兩種引發縮瞳的方法結果不同','看近縮得比照光好，是描述現象，不是一個唯一病名。',[('Light光反射','照光測路徑'),('Near近反應','注視近目標，觀察縮瞳'),('Dissociation分離','光差、近相對保留，可見不同病灶')],'不能由近縮瞳保留，就直接保證調節幅度完全正常。')])
teach(S,'parasympathetic-disorders-1',[
(0,'CN III同時帶轉眼、提眼皮和縮瞳命令','第三神經麻痺的瞳孔可受累，也可能保留。',[('眼外肌','多數由III控制；外直肌VI、上斜肌IV除外'),('提上眼瞼肌','受損可眼瞼下垂'),('副交感纖維','受累時瞳孔較大、縮瞳差')],'眼外下偏、下垂、大瞳孔是典型組合，不是所有III麻痺必有三項。'),
(2,'Adie強直性瞳孔：「強直」在說反應慢','不是瞳孔的肌肉變得更有力。',[('病灶常在','睫狀神經節或節後副交感纖維'),('光差、近較好','近縮瞳與回遠放大常慢、持續'),('去神經超敏感','失去平常神經供應後，肌肉受器對稀釋pilocarpine更敏感')],'稀藥可縮是支持線索，不是所有時期都陽性，也不是只靠滴藥就能唯一診斷。'),
(4,'Argyll Robertson：小、不規則、光差近保留','這是與Adie不同的經典瞳孔組合。',[('典型外觀','常雙側小而不規則'),('反應','照光差，看近縮瞳相對保留'),('經典關聯','神經梅毒；其他光近分離要依病因區分')],'別把所有光近分離都叫AR，也別把近縮瞳直接說成調節一定正常。')])
teach(S,'sympathetic-horner-1',[
(0,'讓瞳孔放大的命令，要繞頸部一大圈','三階是在說三段神經元接力，不是三條獨立通路。',[('第一階','下視丘下行到下頸／上胸脊髓'),('第二階','經肺尖附近上行，到頸上神經節換元'),('第三階','沿內頸動脈等到眼，供應擴張肌與穆勒氏肌')],'汗腺纖維的血管伴行與範圍不同；無汗是否明顯會受病灶位置影響。'),
(2,'Horner：放不大，比另一眼小','眼皮輕垂是穆勒氏肌缺交感，不是整個提眼瞼肌都失效。',[('Miosis','小瞳孔，暗處差異更明顯'),('Ptosis','常較輕的眼瞼下垂'),('Anhidrosis','同側少汗／無汗，依位置不一定都有')],'看起來眼陷可由眼裂變小造成，是假性眼球內陷，不一定真往後退。'),
(4,'NE：神經用來傳話的正腎上腺素','兩種藥分別問「傳話效果」和「末端還能放出多少」。',[('Cocaine古柯鹼','阻再回收；正常NE作用延長，Horner眼擴張較差'),('Hydroxyamphetamine','促完整節後末端釋放NE；節後損害反應較差'),('散瞳遲滯','暗下來時患眼放大較慢，早期差異常較大')],'藥物結果受時程與測試條件影響；這是機制學習，不是自行用藥流程。')])
